const keys = [];
if (!s || s.over || !s.playing) return keys;
const now = s.elapsed_ms || 0;
const px = s.player_x ?? 0, py = s.player_y ?? 0;
const ls = (s.lanterns || []).map(l => ({ i: l.i, x: l.x, y: l.y, b: l.b || 0, touching: !!l.touching, lockedUntil: l.lockedUntil || 0, lit: (l.b || 0) > 0 }));
function addD2(arr){ arr.forEach(l => { l.d2 = (l.x - px) ** 2 + (l.y - py) ** 2; }); return arr; }
const lit = ls.filter(l => l.lit);
const outUnlocked = ls.filter(l => !l.lit && now >= l.lockedUntil);
let target = null;
// Emergency babysit when only one is lit and low
if (lit.length === 1) { const lone = lit[0]; if (lone.b <= 0.35 || outUnlocked.length === 0) target = lone; }
// Prefer nearest unlocked dark; else dimmest lit; else earliest unlocking dark
if (!target && outUnlocked.length) { addD2(outUnlocked); target = outUnlocked.sort((a,b)=>a.d2-b.d2)[0]; }
if (!target && lit.length) { addD2(lit); target = lit.sort((a,b)=>(a.b-b.b)|| (a.d2-b.d2))[0]; }
if (!target) { const anyOut = ls.filter(l=>!l.lit).sort((a,b)=>a.lockedUntil-b.lockedUntil); target = anyOut[0] || null; }
// Stickiness to finish topping off
const m = mem || null;
if (m && m.target && ls.some(l => l.i === m.target.i && l.touching)) m.stickyUntil = now + 250;
const canRetarget = now >= ((m && m.stickyUntil) || 0);
if (!canRetarget && m && m.target) { const keep = ls.find(l => l.i === m.target.i); if (keep) target = keep; }
if (m && (!m.target || (target && m.target.i !== target.i))) { m.aimSince = now; m.retargetAt = now + 120; m.target = target || null; }
// Movement toward target (or center fallback)
const cx = (s.w || 720) / 2, cy = (s.h || 1280) / 2;
const tx = target ? target.x : cx, ty = target ? target.y : cy;
let dx = tx - px, dy = ty - py;
const dead = 4;
let hor = dx > dead ? 1 : (dx < -dead ? -1 : 0);
let ver = dy > dead ? 1 : (dy < -dead ? -1 : 0);
function press(dir){
  if (dir === 'R') keys.push('move right');
  if (dir === 'L') keys.push('move left');
  if (dir === 'U') keys.push('move up');
  if (dir === 'D') keys.push('move down');
}
if (hor > 0) press('R');
if (hor < 0) press('L');
if (ver > 0) press('D');
if (ver < 0) press('U');
// Fail-safe when stuck on a locked, dark lantern
const touchingLockedDark = ls.some(l => !l.lit && l.touching && now < l.lockedUntil);
if (touchingLockedDark && hor === 0 && ver === 0) {
  const choices = outUnlocked.length ? outUnlocked : lit;
  if (choices.length) {
    addD2(choices);
    const near = choices.sort((a,b) => a.d2 - b.d2)[0];
    const ax = Math.sign(near.x - px);
    const ay = Math.sign(near.y - py);
    if (ax > 0) press('R'); else if (ax < 0) press('L');
    if (ay > 0) press('D'); else if (ay < 0) press('U');
  }
}
// Dash logic (tap)
const canDash = !s.dashing && (s.dash || 0) >= 25 && now - ((m && m.lastDashAt) || 0) > 400;
if (target && canDash) {
  const dist = Math.hypot(dx, dy);
  const urgent = (s.lanterns_lit || 0) <= 1 || !target.lit;
  const meterOk = urgent ? (s.dash || 0) >= 25 : (s.dash || 0) >= 60;
  const need = urgent ? dist > 200 : dist > 500;
  if (need && meterOk) { keys.push('dash'); if (m) m.lastDashAt = now; }
}
return keys;

