  } else if (!outUnlocked.length && nd <= 350 && !loneLow) {
    // No options yet, but a drop is imminent: hold center to intercept
    target = { i: -1, x: cx, y: cy, b: 0, lit: false };
  } else {
    // Last resort: babysit the lone lantern
    target = lone;
  }
