    const near = choices.sort((a,b) => a.d2 - b.d2)[0];
    const ax = Math.sign(near.x - px);
    const ay = Math.sign(near.y - py);
    if (ax > 0) press('R'); else if (ax < 0) press('L');
    if (ay > 0) press('D'); else if (ay < 0) press('U');
  }
}

// Dash logic: more aggressive when urgent (one lit or dark target)
const canDash = !s.dashing && (s.dash || 0) >= 20 && now - ((m && m.lastDashAt) || 0) > 300;
if (target && canDash) {
  const dist = Math.hypot(dx, dy);
  const onlyOneLit = (s.lanterns_lit || 0) <= 1;
  const targetIsDark = !target.lit;
  const critical = onlyOneLit && lit.length === 1 && lit[0].b <= safeB;
  const need = targetIsDark ? dist > 140 : onlyOneLit ? dist > 180 : dist > 520;
  const meterOk = (targetIsDark || onlyOneLit) ? (s.dash || 0) >= 20 : (s.dash || 0) >= 60;
  if ((need && meterOk) || critical) { keys.push('dash'); if (m) m.lastDashAt = now; }
}

return keys;

